// === Tab: main ===
let particulas = []; // Arreglo donde guardare las particulas en pantalla
let pixelSteps = 5; // Píxeles entre particulas (ajustado para reducir la cantidad)
let arreglo = []; // Guardaremos lo que queremos que se muestre en pantalla
let tipoLetra = 'Arial';
let arregloIndex = 0;

function setup() {
  createCanvas(720, 480, P2D);
  background(0);

  // Inicio del arreglo
  arreglo.push(tiempo());
  arreglo.push(fecha());
  arreglo.push(" ");
  cambioGrafico(arreglo[arregloIndex]);
}

function draw() {
  // Background & efectos de cola de las particulas
  fill(0, 25); // Aumentado para reducir las partículas persistentes
  noStroke();
  rect(0, 0, width, height);

  for (let i = particulas.length - 1; i >= 0; i--) {
    let particle = particulas[i];
    particle.move();
    particle.display();

    // Eliminio la particula del arreglo si sale de pantalla
    if (particle.died && 
       (particle.posicion.x < 0 || particle.posicion.x > width || 
        particle.posicion.y < 0 || particle.posicion.y > height)) {
      particulas.splice(i, 1);
    }
  }
}

// Hora actual
function tiempo(){
  let h = hour();
  let m = minute();
  let s = second();
  return nf(h,2) + ":" + nf(m,2) + ":" + nf(s,2);
}

// Fecha actual
function fecha(){
  let d = day();
  var m = month();
  let y = year();
  return nf(d,2) + " / " + nf(m,2) + " / " + nf(y,2);
}

// Reinicio el arreglo para volver a tener fecha y hora actuales 
function reiniciar(){
  arreglo = [tiempo(), fecha(), " "];
  arregloIndex = 0;
}

// Mostrar el siguiente grafico en el arreglo
function mousePressed() {
  if (mouseButton === LEFT) {
    arregloIndex += 1;
    cambioGrafico(arreglo[arregloIndex]);

    if (arregloIndex == arreglo.length - 1) { 
      reiniciar();      
    }
  }
}

// Elige una posicion aleatoria desde un punto de particula
function generateRandomPos(x, y, mag) {
  let randomDir = p5.Vector.random2D().mult(mag);
  let posicion = createVector(x, y);

  posicion.add(randomDir);

  return posicion;
}

// Las particulas dibujan el grafico
function cambioGrafico(texto) {
  let grafico = createGraphics(width, height);
  grafico.fill(0);
  grafico.textSize(100);
  grafico.textAlign(CENTER, CENTER);
  grafico.textFont(tipoLetra, 100);
  grafico.text(texto, width / 2, height / 2);
  grafico.loadPixels();

  let conteo = particulas.length;
  let IndexParticulas = 0;
  let IndexCoordenadas = [];

  for (let i = 0; i < (width * height) - 1; i += pixelSteps) {
    IndexCoordenadas.push(i);
  }

  for (let i = 0; i < IndexCoordenadas.length; i++) {
    let randomIndex = floor(random(0, IndexCoordenadas.length));
    let IndexCor = IndexCoordenadas[randomIndex];
    IndexCoordenadas.splice(randomIndex, 1);

    if (grafico.pixels[IndexCor] !== 0) {
      let x = IndexCor % width;
      var y = floor(IndexCor / width);
      let auxParticula;

      if (IndexParticulas < conteo) {
        auxParticula = particulas[IndexParticulas];
        auxParticula.died = false;
        IndexParticulas += 1;
      } else {
        auxParticula = new Particulas();
        let randomPos = generateRandomPos(width / 2, height / 2, (width + height) / 2);
        auxParticula.posicion.x = randomPos.x;
        auxParticula.posicion.y = randomPos.y;
        auxParticula.speed = random(2.0, 4.0);
        auxParticula.fuerza = auxParticula.speed * 0.025;
        auxParticula.size = random(4, 8);
        particulas.push(auxParticula);
      }

      auxParticula.colores = color(random(100,255), random(100,255), random(100,255));
      auxParticula.obj.x = x;
      auxParticula.obj.y = y;
    }
  }

  if (IndexParticulas < conteo) {
    for (let i = IndexParticulas; i < conteo; i++) {
      var particle = particulas[i];
      particle.animacionSalida();
    }
  }
}

// === Tab: Particulas ===
class Particulas {
  constructor() {
    this.posicion = createVector(0, 0);
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.obj = createVector(0, 0);
    this.distObjetivo = 50;
    this.speed = 3.0;
    this.fuerza = 0.08;
    this.size = 5;
    this.died = false;
    this.colores = color(0);
  }

  display() {
    noStroke();
    fill(this.colores);
    ellipse(this.posicion.x, this.posicion.y, this.size, this.size);
  }

  move() {
    let aproximidad = 1;
    let distancia = dist(this.posicion.x, this.posicion.y, this.obj.x, this.obj.y);
    if (distancia < this.distObjetivo) {
      aproximidad = distancia / this.distObjetivo;
    }

    let toObjetivo = createVector(this.obj.x, this.obj.y);
    toObjetivo.sub(this.posicion);
    toObjetivo.normalize();
    toObjetivo.mult(this.speed * aproximidad);

    let direccion = createVector(toObjetivo.x, toObjetivo.y);
    direccion.sub(this.vel);
    direccion.normalize();
    direccion.mult(this.fuerza);

    this.acc.add(direccion);
    this.vel.add(this.acc);
    this.posicion.add(this.vel);
    this.acc.mult(0);
  }

  animacionSalida() {
    if (!this.died) {
      var randomPos = generateRandomPos(width / 2, height / 2, (width + height) / 2);
      this.obj.x = randomPos.x;
      this.obj.y = randomPos.y;
      this.colores = color(255);
      this.died = true;
    }
  }
}

